// Status of the Bank Employment Link session.
//
// `APPROVED`: User has approved and verified their employment.
//
// `NO_EMPLOYERS_FOUND`: We attempted, but were unable to find any employment in the connected account.
//
// `EMPLOYER_NOT_LISTED`: The user explicitly indicated that they did not see their current or previous employer in the list of employer names found.
//
// `STARTED`: The user began the bank employment portion of the link flow.
//
// `INTERNAL_ERROR`: The user encountered an internal error.
type CreditSessionBankEmploymentStatus string

const (
	CreditSessionBankEmploymentStatusApproved          CreditSessionBankEmploymentStatus = "APPROVED"
	CreditSessionBankEmploymentStatusNoEmployersFound  CreditSessionBankEmploymentStatus = "NO_EMPLOYERS_FOUND"
	CreditSessionBankEmploymentStatusEmployerNotListed CreditSessionBankEmploymentStatus = "EMPLOYER_NOT_LISTED"
	CreditSessionBankEmploymentStatusStarted           CreditSessionBankEmploymentStatus = "STARTED"
	CreditSessionBankEmploymentStatusInternalError     CreditSessionBankEmploymentStatus = "INTERNAL_ERROR"
)

func NewCreditSessionBankEmploymentStatusFromString(s string) (CreditSessionBankEmploymentStatus, error) {
	switch s {
	case "APPROVED":
		return CreditSessionBankEmploymentStatusApproved, nil
	case "NO_EMPLOYERS_FOUND":
		return CreditSessionBankEmploymentStatusNoEmployersFound, nil
	case "EMPLOYER_NOT_LISTED":
		return CreditSessionBankEmploymentStatusEmployerNotListed, nil
	case "STARTED":
		return CreditSessionBankEmploymentStatusStarted, nil
	case "INTERNAL_ERROR":
		return CreditSessionBankEmploymentStatusInternalError, nil
	}
	var t CreditSessionBankEmploymentStatus
	return "", fmt.Errorf("%s is not a valid %T", s, t)
}

